knowledge_points.worked_example:
ages = {'ana': 31, 'bo': 27}
print(ages['bo'])  # 27
Each entry is key: value; d[key] returns the value stored under that key.

menu = {'tea': 2.5, 'cake': 4.0, 'soup': 'sold out'}
print(len(menu))  # 3
empty = {}
print(len(empty))  # 0
len counts key-value pairs; {} is an empty dict ready to be filled.

pairs = [('ana', 31), ('bo', 27)]
for name, age in pairs:
    if name == 'bo':
        print(age)  # 27
ages = {'ana': 31, 'bo': 27}
print(ages['bo'])  # 27
Same data: the list needs a search loop, the dict answers in one step.

ages = {'ana': 31, 'bo': 27}
print(ages['Ana'])  # KeyError: 'Ana'
Keys must match exactly, including case; a missing key stops the program.

stock = {}
stock['apple'] = 3
stock['pear'] = 5
print(stock)  # {'apple': 3, 'pear': 5}
Start from {} and assign: a key that is not there yet is created.

stock = {'apple': 3}
stock['apple'] = 10
stock['apple'] += 1
print(stock)  # {'apple': 11}
Keys are unique: assignment replaces the old value. += on a key that does not exist raises KeyError.

stock = {'apple': 3, 'pear': 5}
del stock['pear']
n = stock.pop('apple')
print(n, stock)  # 3 {}
print(stock.pop('kiwi', 0))  # 0
pop returns the removed value; del and pop(key) raise KeyError if absent, pop(key, default) does not.

stock = {'apple': 3, 'pear': 5}
stock.update({'apple': 4, 'kiwi': 2})
print(stock)  # {'apple': 4, 'pear': 5, 'kiwi': 2}
print({'a': 1} | {'a': 9, 'b': 2})  # {'a': 9, 'b': 2}
update changes the dict in place; | builds a new one. On a shared key the right-hand value wins.

ages = {'ana': 31, 'bo': 27}
name = 'cy'
if name in ages:
    print(ages[name])
else:
    print('unknown')  # unknown
Guard the lookup with in so a missing key takes the else branch instead of crashing.

ages = {'ana': 31, 'bo': 27}
print(ages.get('cy', 0))  # 0
print(ages.get('bo', 0))  # 27
print(ages)  # {'ana': 31, 'bo': 27}
The default is used only when the key is missing, and get never adds the key to the dict.

prices = {'tea': 2.5, 'cake': 4.0}
for item in prices:
    print(item, prices[item])
# tea 2.5
# cake 4.0
Keys come out in the order they were added; use d[key] inside the loop for the value.

prices = {'tea': 2.5, 'cake': 4.0}
total = 0
for p in prices.values():
    total += p
print(total)  # 6.5
values() skips the keys entirely; it suits totals, maxima and counts.

prices = {'tea': 2.5, 'cake': 4.0}
for item, price in prices.items():
    print(item, 'costs', price)
# tea costs 2.5
# cake costs 4.0
Each item is a (key, value) tuple; unpack it straight into two names.

ages = {'ana': 31, 'bo': 27, 'cy': 27}
for name, age in ages.items():
    if age == 27:
        print(name)
# bo
# cy
Lookup is fast only by key; searching by value means checking every item, and several keys may match.

counts = {}
for ch in 'banana':
    if ch in counts:
        counts[ch] += 1
    else:
        counts[ch] = 1
print(counts)  # {'b': 1, 'a': 3, 'n': 2}
First sighting stores 1; every later sighting adds 1.

counts = {}
for ch in 'banana':
    counts[ch] = counts.get(ch, 0) + 1
print(counts)  # {'b': 1, 'a': 3, 'n': 2}
get returns 0 for an unseen key, so one line replaces the if/else.

text = 'The cat and the hat'
counts = {}
for w in text.lower().split():
    counts[w] = counts.get(w, 0) + 1
print(counts['the'])  # 2
Normalise case, split into words, then count as before.

counts = {'b': 1, 'a': 3, 'n': 2}
best = None
for ch, n in counts.items():
    if best is None or n > counts[best]:
        best = ch
print(best)  # a
The max-so-far pattern, run over items(): remember the key, compare its count.

groups = {}
for w in ['ant', 'bee', 'ape']:
    first = w[0]
    if first not in groups:
        groups[first] = []
    groups[first].append(w)
print(groups)  # {'a': ['ant', 'ape'], 'b': ['bee']}
Same shape as counting, but the 'start' value is an empty list and the 'add' is append.

groups = {}
for w in ['ant', 'bee', 'ape']:
    groups[w[0]] = [w]
print(groups)  # {'a': ['ape'], 'b': ['bee']}
Assigning a fresh list each time throws away earlier members; only the last one survives.

groups = {}
for w in ['ant', 'bee', 'ape']:
    groups.setdefault(w[0], []).append(w)
print(groups)  # {'a': ['ant', 'ape'], 'b': ['bee']}
setdefault returns the existing list, or stores and returns the default when the key is new.

grades = {'ana': 'A', 'bo': 'B', 'cy': 'A'}
by_grade = {}
for name, g in grades.items():
    by_grade.setdefault(g, []).append(name)
print(by_grade)  # {'A': ['ana', 'cy'], 'B': ['bo']}
Several keys can share a value, so the inverted dict needs lists.

counts = {'b': 1, 'a': 3, 'c': 2}
flipped = []
for k, v in counts.items():
    flipped.append((v, k))
print(sorted(flipped, reverse=True))  # [(3, 'a'), (2, 'c'), (1, 'b')]
Tuples sort by their first item, so putting the value first sorts by value.

counts = {'b': 1, 'a': 3, 'c': 2}
print(sorted(counts, key=counts.get, reverse=True))  # ['a', 'c', 'b']
counts.get is the function that maps each key to its value; no () after it.

counts = {'the': 3, 'and': 2, 'cat': 1, 'hat': 1}
for word in sorted(counts, key=counts.get, reverse=True)[:2]:
    print(word, counts[word])
# the 3
# and 2
Sort descending by value, slice the first n, then print.

phone = {('Ana', 'Lee'): '555-1234', ('Bo', 'Kim'): '555-9876'}
for (first, last), num in phone.items():
    print(last, first, num)
# Lee Ana 555-1234
# Kim Bo 555-9876
Nested parentheses in the loop target unpack the key tuple and the value in one step.

a = {'x': 1}
b = a
b['y'] = 2
print(a)  # {'x': 1, 'y': 2}
Assignment copies the reference, not the dict, exactly as with lists.

a = {'x': 1}
b = a.copy()
b['y'] = 2
print(a, b)  # {'x': 1} {'x': 1, 'y': 2}
dict.copy() (or dict(a)) builds a new outer dict; inner lists would still be shared.

def register(roster, name):
    roster[name] = 0

team = {}
register(team, 'ana')
print(team)  # {'ana': 0}
The parameter is another name for the same dict; no return is needed for the change to show.

stock = {'apple': 0, 'pear': 5}
for k in stock:
    if stock[k] == 0:
        del stock[k]  # RuntimeError: dictionary changed size during iteration
Loop over a copy instead: for k in stock.copy(): ... del stock[k] works. Changing values (not keys) in the loop is fine.

seen = set()
repeats = set()
for x in [4, 7, 4, 1, 7]:
    if x in seen:
        repeats.add(x)
    else:
        seen.add(x)
print(sorted(repeats))  # [4, 7]
Remember what has appeared; a value already in seen is a duplicate.

a = {1, 2, 3}
b = {3, 4}
print(sorted(a | b))  # [1, 2, 3, 4]
print(sorted(a.union([4, 5])))  # [1, 2, 3, 4, 5]
| combines both sets; the method form union() also accepts a list.

likes_ana = {'tea', 'jazz', 'chess'}
likes_bo = {'chess', 'tea', 'golf'}
print(sorted(likes_ana & likes_bo))  # ['chess', 'tea']
& keeps only values in both, like 'and' for membership.

a = {1, 2, 3}
b = {3, 4}
print(sorted(a - b))  # [1, 2]
print(sorted(b - a))  # [4]
print(sorted(a ^ b))  # [1, 2, 4]
a - b is 'in a but not b' (order matters); ^ is 'in exactly one'.

need = {'eggs', 'milk'}
have = {'milk', 'eggs', 'jam'}
print(need <= have)  # True
print(set([1, 2, 2]) == set([2, 1]))  # True
<= asks 'is every item of the left in the right?'; == on sets ignores order and repeats.

grid = [[1, 2, 3], [4, 9, 6]]
for r in range(len(grid)):
    for c in range(len(grid[r])):
        if grid[r][c] == 9:
            print('found at', r, c)  # found at 1 1
Index loops give you r and c, needed to report or change a position.

people = [{'name': 'Ana', 'age': 31}, {'name': 'Bo', 'age': 27}]
for p in people:
    if p['age'] > 30:
        print(p['name'])  # Ana
The loop variable is one whole record each time.

grades = {'ana': [90, 85], 'bo': [70]}
grades['bo'].append(88)
print(grades)  # {'ana': [90, 85], 'bo': [70, 88]}
grades['bo'] is the stored list itself, so append changes it in place: no reassignment needed.

people = {'ana': {'age': 31, 'city': 'Oslo'},
          'bo': {'age': 27, 'city': 'Lima'}}
print(people['bo']['city'])  # Lima
people['ana']['age'] += 1
print(people['ana'])  # {'age': 32, 'city': 'Oslo'}
Two keys in a row: the outer picks the person, the inner picks the field.

data = {'users': [{'name': 'Ana', 'tags': ['admin', 'dev']}]}
print(data['users'][0]['tags'][-1])  # dev
Read left to right: dict, then list, then dict, then list; each step's result is what the next step indexes.

data = {'users': [{'name': 'Ana'}, {'name': 'Bo'}]}
for user in data['users']:
    print(user['name'])
# Ana
# Bo
Navigate to the list once, then loop over its items.

data = {'users': [{'name': 'Ana'}]}
print(data['users']['name'])  # TypeError: list indices must be integers or slices, not str
KeyError: a missing key; IndexError: a list too short; TypeError: you used a key on a list (or an index on the wrong type).

words = ['kiwi', 'fig']
print({w: len(w) for w in words})  # {'kiwi': 4, 'fig': 3}
Like a list comprehension, but with braces and key: value in front.

nums = [1, 2, 3, 4]
print({n: n * n for n in nums if n % 2 == 0})  # {2: 4, 4: 16}
Only items passing the if get an entry.

words = ['ant', 'bee', 'ape']
print({w[0]: w for w in words})  # {'a': 'ape', 'b': 'bee'}
Each new value for an existing key overwrites the old one; to keep all of them, group into lists instead.

prices = {'tea': 2, 'cake': 4}
print({k: v * 2 for k, v in prices.items()})  # {'tea': 4, 'cake': 8}
Loop over items(), keep the key, transform the value.

scores = {'ana': 72, 'bo': 45, 'cy': 90}
print({k: v for k, v in scores.items() if v >= 50})  # {'ana': 72, 'cy': 90}
A new dict with only the passing entries; the original is unchanged (and safe, unlike deleting while looping).

code = {'a': 1, 'b': 2}
print({v: k for k, v in code.items()})  # {1: 'a', 2: 'b'}
print({v: k for k, v in {'a': 1, 'b': 1}.items()})  # {1: 'b'}
Works when values are unique; duplicate values collapse to one key, so use grouping into lists in that case.

def balanced(text):
    pairs = {')': '(', ']': '['}
    stack = []
    for ch in text:
        if ch in '([':
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

print(balanced('([])'), balanced('(]'), balanced('(('))  # True False False
Push every opener; each closer must match the most recent opener; leftovers mean unbalanced.

from collections import defaultdict
counts = defaultdict(int)
for ch in 'banana':
    counts[ch] += 1
print(dict(counts))  # {'b': 1, 'a': 3, 'n': 2}
A missing key starts at int() == 0, so += just works. dict() turns it back into a plain dict for printing.

from collections import defaultdict
groups = defaultdict(list)
for w in ['ant', 'bee', 'ape']:
    groups[w[0]].append(w)
print(dict(groups))  # {'a': ['ant', 'ape'], 'b': ['bee']}
A missing key starts as a new empty list; no if-not-in or setdefault needed.
